-- ---------------------------------------------------------------------------------------------
-- Stock levels and the append-only movement ledger
-- ---------------------------------------------------------------------------------------------
create table retailos.inventory_balances (
  tenant_id  uuid not null,
  branch_id  uuid not null,
  variant_id uuid not null,
  on_hand    integer not null default 0 check (on_hand >= 0),
  updated_at timestamptz not null default now(),
  primary key (branch_id, variant_id),
  foreign key (tenant_id, branch_id) references retailos.branches (tenant_id, id) on delete restrict,
  foreign key (tenant_id, variant_id) references retailos.product_variants (tenant_id, id) on delete restrict
);
create index inventory_balances_variant_idx on retailos.inventory_balances (tenant_id, variant_id);

create table retailos.inventory_movements (
  id                bigint generated always as identity primary key,
  tenant_id         uuid not null,
  branch_id         uuid not null,
  movement_type     text not null check (movement_type in
                      ('OPENING', 'PURCHASE_RECEIPT', 'SALE', 'SALE_VOID', 'SALE_RETURN', 'ADJUSTMENT_IN', 'ADJUSTMENT_OUT')),
  item_type         text not null check (item_type in ('VARIANT', 'JEWELLERY_ITEM')),
  variant_id        uuid,
  jewellery_item_id uuid,
  quantity_delta    integer not null check (quantity_delta <> 0),
  balance_after     integer check (balance_after is null or balance_after >= 0),
  reference_type    text,
  reference_id      uuid,
  reason_code       text,
  note              text,
  business_date     date not null,
  created_by        uuid default auth.uid(),
  created_at        timestamptz not null default now(),
  check (num_nonnulls(variant_id, jewellery_item_id) = 1),
  check ((item_type = 'VARIANT') = (variant_id is not null)),
  check (item_type = 'VARIANT' or quantity_delta in (-1, 1)),
  foreign key (tenant_id, branch_id) references retailos.branches (tenant_id, id) on delete restrict,
  foreign key (tenant_id, variant_id) references retailos.product_variants (tenant_id, id) on delete restrict,
  foreign key (tenant_id, jewellery_item_id) references retailos.jewellery_items (tenant_id, id) on delete restrict
);
create index inventory_movements_variant_idx on retailos.inventory_movements (tenant_id, branch_id, variant_id, id);
create index inventory_movements_item_idx on retailos.inventory_movements (tenant_id, jewellery_item_id, id);
create index inventory_movements_ref_idx on retailos.inventory_movements (reference_type, reference_id);

create or replace function retailos_private.ledger_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception '% is append-only', tg_table_name using errcode = '42501';
end;
$$;
create trigger inventory_movements_no_change before update or delete on retailos.inventory_movements
  for each row execute function retailos_private.ledger_immutable();
create trigger inventory_movements_no_truncate before truncate on retailos.inventory_movements
