$$;

-- ---------------------------------------------------------------------------------------------
-- Gapless document numbers and idempotency keys (internal; no API access)
-- ---------------------------------------------------------------------------------------------
create table retailos.document_sequences (
  tenant_id      uuid not null,
  branch_id      uuid not null,
  document_type  text not null check (document_type in ('INVOICE', 'CREDIT_NOTE', 'ADJUSTMENT')),
  financial_year text not null default '',
  next_number    bigint not null default 1 check (next_number >= 1),
  primary key (tenant_id, branch_id, document_type, financial_year),
  foreign key (tenant_id, branch_id) references retailos.branches (tenant_id, id) on delete restrict
);

-- Allocate the next number. The row update takes a lock held until the caller's transaction ends, so
-- allocation is serialised per branch/type/year, and a rollback gives the number back: no gaps.
create or replace function retailos_private.next_document_number(p_tenant uuid, p_branch uuid, p_type text, p_fy text)
returns bigint
language plpgsql
security definer set search_path = ''
as $$
declare
  v_next bigint;
begin
  insert into retailos.document_sequences (tenant_id, branch_id, document_type, financial_year)
    values (p_tenant, p_branch, p_type, p_fy)
  on conflict do nothing;
  update retailos.document_sequences set next_number = next_number + 1
    where tenant_id = p_tenant and branch_id = p_branch and document_type = p_type and financial_year = p_fy
    returning next_number - 1 into v_next;
  return v_next;
end;
$$;

create table retailos.idempotency_keys (
  tenant_id     uuid not null references retailos.tenants (id) on delete restrict,
  scope         text not null,
  key           uuid not null,
  request_hash  text not null,
  actor_user_id uuid not null,
  status        text not null default 'PENDING' check (status in ('PENDING', 'COMPLETED')),
  response      jsonb,
  created_at    timestamptz not null default now(),
  completed_at  timestamptz,
  primary key (tenant_id, scope, key)
);

-- Start an idempotent operation.
--   returns NULL        -> this is the first time: proceed.
--   returns a jsonb     -> the same request already completed: return this stored response unchanged.
-- A concurrent duplicate blocks inside the INSERT until the first transaction commits or rolls back.
-- The key is bound to the user who first used it and to the exact request contents.
create or replace function retailos_private.idem_begin(p_tenant uuid, p_scope text, p_key uuid, p_hash text)
returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_inserted integer;
  v_row retailos.idempotency_keys;
begin
  insert into retailos.idempotency_keys (tenant_id, scope, key, request_hash, actor_user_id)
    values (p_tenant, p_scope, p_key, p_hash, (select auth.uid()))
  on conflict do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 1 then
    return null;
  end if;
  select * into v_row from retailos.idempotency_keys
    where tenant_id = p_tenant and scope = p_scope and key = p_key;
  if v_row.request_hash <> p_hash or v_row.actor_user_id is distinct from (select auth.uid()) then
    perform retailos_private.fail('IDEMPOTENCY_KEY_REUSED');
  end if;
  if v_row.status <> 'COMPLETED' then
    perform retailos_private.fail('CONCURRENT_UPDATE');
  end if;
  return v_row.response;
end;
$$;

create or replace function retailos_private.idem_complete(p_tenant uuid, p_scope text, p_key uuid, p_response jsonb)
returns void
language sql
security definer set search_path = ''
as $$
  update retailos.idempotency_keys
     set status = 'COMPLETED', response = p_response, completed_at = now()
   where tenant_id = p_tenant and scope = p_scope and key = p_key;
$$;

-- ---------------------------------------------------------------------------------------------
-- Stock adjustment (reason required, idempotent, audited)
-- ---------------------------------------------------------------------------------------------
create or replace function retailos.inventory_adjust(
  p_branch uuid, p_variant uuid, p_delta integer, p_reason_code text, p_note text, p_idempotency_key uuid
) returns jsonb
language plpgsql
security definer set search_path = ''
as $$
declare
  v_tenant uuid;
  v_hash text;
  v_replay jsonb;
  v_after integer;
  v_response jsonb;
  v_date date;
begin
  perform retailos_private.assert_branch_permission(p_branch, 'inventory.adjust');
  select tenant_id into v_tenant from retailos.branches where id = p_branch;
  if p_delta is null or p_delta = 0 or abs(p_delta) > 100000 then perform retailos_private.fail('VALIDATION_ERROR'); end if;
  if p_reason_code not in ('COUNT_CORRECTION', 'DAMAGE', 'LOSS', 'FOUND', 'WRITE_OFF', 'OTHER') then
    perform retailos_private.fail('VALIDATION_ERROR', jsonb_build_object('field', 'reason'));
  end if;
  if not exists (select 1 from retailos.product_variants where tenant_id = v_tenant and id = p_variant) then
    perform retailos_private.fail('ITEM_NOT_FOUND');
  end if;

  v_hash := encode(sha256(convert_to(jsonb_build_object('b', p_branch, 'v', p_variant, 'd', p_delta, 'r', p_reason_code, 'n', coalesce(p_note, ''))::text, 'UTF8')), 'hex');
  v_replay := retailos_private.idem_begin(v_tenant, 'inventory_adjust', p_idempotency_key, v_hash);
  if v_replay is not null then return v_replay || jsonb_build_object('replayed', true); end if;

  v_date := (now() at time zone (select timezone from retailos.branches where id = p_branch))::date;
  -- lock the balance row so a concurrent sale or adjustment cannot interleave
  insert into retailos.inventory_balances (tenant_id, branch_id, variant_id) values (v_tenant, p_branch, p_variant)
    on conflict (branch_id, variant_id) do nothing;
  perform 1 from retailos.inventory_balances where branch_id = p_branch and variant_id = p_variant for update;
  v_after := retailos_private.apply_variant_movement(v_tenant, p_branch, p_variant, p_delta,
              case when p_delta > 0 then 'ADJUSTMENT_IN' else 'ADJUSTMENT_OUT' end,
              'ADJUSTMENT', p_idempotency_key, p_reason_code, p_note, v_date);
  perform retailos_private.write_audit(v_tenant, p_branch, 'inventory.adjust', 'product_variant', p_variant, null,
            jsonb_build_object('delta', p_delta, 'balanceAfter', v_after), p_reason_code, jsonb_build_object('note', p_note));
  v_response := jsonb_build_object('variantId', p_variant, 'balanceAfter', v_after, 'replayed', false);
  perform retailos_private.idem_complete(v_tenant, 'inventory_adjust', p_idempotency_key, v_response);
  return v_response;
end;
$$;

