grant select on retailos.inventory_balances, retailos.inventory_movements to authenticated;
-- document_sequences and idempotency_keys: no privileges for API roles at all.

alter table retailos.inventory_balances  enable row level security;
alter table retailos.inventory_movements enable row level security;
alter table retailos.document_sequences  enable row level security;
alter table retailos.idempotency_keys    enable row level security;

-- Stock levels are visible only with inventory.view (a cashier sees availability while billing,
-- computed inside the billing functions, but not the stock ledger).
create policy inventory_balances_read on retailos.inventory_balances for select to authenticated
  using (retailos_private.has_branch_permission(branch_id, 'inventory.view'));
create policy inventory_movements_read on retailos.inventory_movements for select to authenticated
  using (retailos_private.has_branch_permission(branch_id, 'inventory.view'));

revoke execute on all functions in schema retailos_private from public, anon;
